INSERT INTO `news` (`id`, `title`, `slug`, `content`, `image`, `tags`, `category_id`, `subcategory_id`, `author`, `status`, `is_featured`, `created_at`, `updated_at`) VALUES
(1, 'স্বাধীনতা হীনতায়', 'স্বাধীনতা-হীনতায়', '<p style=\"text-align:justify\">অগ্নিগর্ভ পাকিস্তান অধিকৃত কাশ্মীর (পিওকে)। রাস্তায় ছড়িয়ে পাথর, পোড়া গাড়ি! সরকার বিরোধী বিক্ষোভ দমনে নির্বিচারে গুলি ফিল্ড মার্শাল আসিম মুনিরের ‘ঘাতক’ সেনাবাহিনীর। প্রাণ হারিয়েছেন অন্তত ৯০ জন নিরপরাধ মানুষ। ধরপাকড় চলছে। তবুও থামেনি সরকার বিরোধী বিক্ষোভ। জ্বলে ওঠে রাওয়ালকোট, মিরপুর, কোটলি, নীলম ভ্যালি সহ নানা এলাকা। ইসলামাবাদ টের পাচ্ছে, অবৈধভাবে দখলে থাকা কাশ্মীরই এখন পাকিস্তানের গলার কাঁটা!</p>\r\n\r\n<p style=\"text-align:justify\">পাক প্রশাসনের বিরুদ্ধে এই বিক্ষোভের সূত্রপাত রাওয়ালকোটে। সেখানেই নিরাপত্তাবাহিনীর গুলিতে নিহত হয়েছিলেন এক ব্যবসায়ী। তারপরেই সেই বিক্ষোভ পাক অধিকৃত কাশ্মীরের অন্য শহরগুলিতেও ছড়িয়ে পড়েছিল। এমনকি লন্ডনে পাক হাই কমিশন এবং ব্রিটেনে পাকিস্তানের অন্য কূটনৈতিক দপ্তরগুলির বাইরেও সেই বিক্ষোভের আঁচ ছড়িয়েছে। অবস্থা আয়ত্তের বাইরে চলে যাওয়ায় গত ৫ জুন প্রশাসন নাগরিক সংগঠন ‘জয়েন্ট আওয়ামি অ্যাকশন কমিটি’ (জেএএসি)-কে নিষিদ্ধ ঘোষণা করে। তাতে পাক সেনার অত্যাচারের বিরুদ্ধে বিক্ষোভ আরও বাড়ে। প্রতিবাদীদের দমন করতে ধারাবাহিক অভিযান শুরু করে পাকিস্তানি বাহিনী। বন্ধ করে দেওয়া হয় পাক অধিকৃত কাশ্মীরের মোবাইল নেটওয়ার্ক। সাধারণ বাসিন্দাদের উপর চাপানো হয় বিভিন্ন বিধিনিষেধও। এর জেরে নিত্যপ্রয়োজনীয় সামগ্রী, খাবার এবং ওষুধ জোগাড় করতে হিমশিম পাক অধিকৃত কাশ্মীরের বাসিন্দারা। গত ৯ জুন থেকে ৩৮ দফা দাবিতে শুরু হয় আন্দোলনের নতুন পর্যায়। তাতে ৪০ জনেরও বেশি বিক্ষোভকারীকে হত্যার অভিযোগ উঠেছে পাক সেনার বিরুদ্ধে। প্রতিক্রিয়া জানাতে গিয়ে পাকিস্তানের প্রতিরক্ষামন্ত্রী খাজা আসিফ বলেছিলেন, রাওয়ালকোট এবং মিরপুরের বাসিন্দারা ‘আসল কাশ্মীরি নন’। আর সেটাই ছিল বিক্ষোভের আগুনে ঘি ঢালা!</p>\r\n\r\n<p style=\"text-align:justify\">পাল্টা জবাবে বিদ্রোহীরাও ‘অন্য পথ’ নেওয়ার হুঁশিয়ারি দিয়েছেন। দীর্ঘ দিন ধরেই পাক সেনার অত্যাচারের বিরুদ্ধে প্রতিবাদ-আন্দোলন করছেন পাক অধিকৃত কাশ্মীরের বাসিন্দারা। অর্থনৈতিক সংকট, বেকারত্ব, বিদ্যুতের বর্ধিত মূল্য, মূল্যস্ফীতি, সাধারণ নাগরিকদের প্রতি বঞ্চনা, একের পর এক বিধিনিষেধ চাপানোর জেরে পাক-অধিকৃত কাশ্মীরে দীর্ঘদিন ধরেই ক্ষোভ জমছিল। তাতে নতুন মাত্রা এনেছে, পাক অধিকৃত কাশ্মীরের ভোট এবং সংরক্ষিত ১২টি আসন। সেই আসনগুলিই এখন অধিকৃত কাশ্মীরে সংঘাতের কেন্দ্রবিন্দু।</p>\r\n\r\n<p style=\"text-align:justify\">রাজপথ থেকে শুরু করে ফসলের খেত— পাক অধিকৃত কাশ্মীরের সবখানেই এখন কেবলই সাধারণ মানুষের রক্তের দাগ এবং স্বজনহারা পরিবারের কান্নার রোল। গ্রামে গ্রামে বাজারঘাট বন্ধ করে দিয়ে পাক সেনার নির্মম হিংসার বিরুদ্ধে প্রতিবাদ মিছিল বের করছেন সাধারণ মানুষ। দফায় দফায় এখন একটাই স্লোগান প্রতিধ্বনিত হচ্ছে— ‘ইয়ে জো দেহশাতগার্দি হ্যায়, ইসকে পিছে ওয়ার্দি হ্যায়’। বাংলা করলে দাঁড়ায়, এই যে সন্ত্রাসবাদ, এর পিছনে উর্দি রয়েছে। পাকিস্তান থেকে আজাদি চাইছে ‘আজাদ কাশ্মীর’!</p>\r\n\r\n<p style=\"text-align:justify\">পাক অধিকৃত কাশ্মীরের আইনসভায় মোট ৫৩ জন সদস্যের মধ্যে এই উদ্বাস্তুদের জন্য ১২টি আসন সংরক্ষিত হয়েছিল। এর মধ্যে ৬টি আসন কাশ্মীর উপত্যকা এবং ৬টি আসন জম্মু থেকে আসা উদ্বাস্তুদের জন্য সংরক্ষিত। বিভিন্ন সংগঠনের যৌথমঞ্চ, নাগরিক সংগঠন জেএএসি ওই ১২টি সংরক্ষিত আসন তুলে দেওয়ার দাবি তুলেছে। তাদের অভিযোগ, ১৯৪৭ এবং তারপর ১৯৬৫ সাল পর্যন্ত জম্মু-কাশ্মীর থেকে বহু মানুষ পাকিস্তানে স্থানান্তরিত হয়েছেন। বিশেষ করে জম্মু, পুঞ্চ এবং রাজৌরি থেকে। এই মানুষদের পাকিস্তানে ‘উদ্বাস্তু’ ঘোষণা করা হয়েছে। ওই উদ্বাস্তুরা যেহেতু পাকিস্তানের বিভিন্ন প্রান্তে ছড়িয়ে ছিটিয়ে বসতি স্থাপন করেছেন, তাই সংরক্ষিত আসনগুলির ‘উদ্বাস্তু’ ভোটারদের সঙ্গে পিওকে-র কোনো সম্পর্ক নেই। পাক অধিকৃত কাশ্মীরের সরকারের উপর নিয়ন্ত্রণ রাখতে এবং সেখানকার রাজনীতিকে প্রভাবিত করতে ইসলামাবাদের এই আসনগুলি জরুরি। তারা সেই ‘উদ্বাস্তু’ ভোটারদের হাতিয়ার করছে। জেএএসি-র অভিযোগ, পিওকে-র বিধানসভায় নিজেদের কর্মসূচি চাপিয়ে দেওয়ার জন্য ইসলামাবাদ এই আসনগুলিকে ব্যবহার করছে। ওই আসনগুলি থেকে ‘সাজানো’ নির্বাচনে জয়ী প্রতিনিধিদের মাধ্যমে পাক অধিকৃত কাশ্মীরের রাজনীতিকে নিয়ন্ত্রণ করে থাকে ইসলামাবাদ। এই উদ্বাস্তু আসনগুলি রাজনৈতিক ভারসাম্য নষ্ট করছে। সেখানকার স্থানীয় বাসিন্দাদের রাজনৈতিক কণ্ঠস্বরকে দুর্বল করে দিচ্ছে।</p>\r\n\r\n<p style=\"text-align:justify\">পাকিস্তানের সুপ্রিম কোর্ট রায় দিয়েছে, আসনগুলি সংবিধানের আওতায় সুরক্ষিত এবং কেবল আনুষ্ঠানিক সাংবিধানিক সংশোধনীর মাধ্যমেই এগুলি বিলুপ্ত করা সম্ভব। ফলে, আরও তীব্র হয়েছে গণ-আন্দোলন। জেএএসি-র নেতা সর্দার আমান খান সম্প্রতি পাক মদতপুষ্ট সন্ত্রাসবাদেরও বিরুদ্ধে আওয়াজ তুলেছেন। তিনি অভিযোগ করেছেন, পাকিস্তানের সামরিক বাহিনীই মূলত ওই স্থানান্তরিত কাশ্মীরিদের মাধ্যমে জম্মু ও কাশ্মীরে সন্ত্রাস রপ্তানি ও অস্ত্র সরবরাহ করে। পাক অধিকৃত কাশ্মীরে পাকিস্তানি নির্যাতন প্রতিরোধে হস্তক্ষেপের জন্য নয়াদিল্লির কাছে আবেদনও জানিয়েছেন তিনি। পাকিস্তান শেহবাজ শরিফের নেতৃত্বাধীন সরকারকে সতর্ক করে আমান এ-ও মন্তব্য করেন যে, যদি তাঁদের আন্দোলনের ৩৮টি দাবি মেনে নেওয়া না হয় বা বাস্তবায়ন না করা হয়, তবে বিষয়টি আর কেবল দাবির মধ্যে সীমাবদ্ধ থাকবে না। এক বৃহত্তর আন্দোলনে পরিণত হবে।</p>\r\n\r\n<p style=\"text-align:justify\">ভাবুন, নিজস্ব প্রতিনিধি পরিষদ থাকলেও আজাদ কাশ্মীরের অর্থনৈতিক ও ভূসম্পদ বিষয়ে ‘সুপারিশ করে’ আজাদ কাশ্মীর কাউন্সিল নামের সংস্থা। সদর দপ্তর ইসলামাবাদে। এর চেয়ারম্যান পাকিস্তানের প্রধানমন্ত্রী। ১৪ সদস্যের এই পরিষদের ৫ জনকেই মনোনয়ন দেন চেয়ারম্যান। বাকি ব্যক্তিরা স্থানীয় প্রতিনিধি পরিষদের সদস্য হয়ে থাকেন। ইসলামাবাদের অঙ্গুলিহেলন মানবে কেন পিওকের বাসিন্দারা?</p>\r\n\r\n<p style=\"text-align:justify\">প্রশ্ন উঠেছে, বিদ্রোহীদের ‘অন্য পথ’ নেওয়ার হুঁশিয়ারি আসলে কী? তা হলে কি ভারতের সঙ্গে যোগাযোগ এবং সুসম্পর্ক বজায় রাখতে চাইছেন জেএএসি নেতারা? ভারতের সঙ্গে পিওকে-কে মিলিয়ে দেওয়ার চেষ্টা করছেন? পাকিস্তান থেকে ভেঙে স্বাধীন ভাবে আত্মপ্রকাশের পর্ব শুরু হয়ে গেল কি না, সেই প্রশ্নও উঠে আসছে। এই আঁচ পেয়েই পিওকে-তে সংবাদমাধ্যমের প্রবেশ প্রায় নিষিদ্ধ করে দিয়েছে পাক সরকার। বলা হয়েছে, পিওকে-তে খবর সংগ্রহ করতে হলে সরকারের অনুমতি নিতে হবে। যে অভিমুখে দুই প্রদেশ বালুচিস্তান ও খাইবার পাখতুনখোয়া এবং দুই বিশেষ অঞ্চল পাক-অধিকৃত কাশ্মীর ও গিলগিট বাল্টিস্তানে জনতার ক্ষোভ এগোচ্ছে, তাতে পাক সরকারের দুশ্চিন্তার কারণ রয়েছে বলে মনে করছেন বিশ্লেষকরা। ইতিমধ্যে ১১ আগস্ট ‘রিপাবলিক অব বালুচিস্তান’ আত্মপ্রকাশ করবে বলে জানিয়েছেন বালুচ নেতৃত্ব। অভিযোগ, গত সাত দশকে বালুচিস্তান প্রদেশ থেকে খনিজ উত্তোলন করে, তা বিক্রি করে পাকিস্তান কোটি কোটি ডলার উপার্জন করলেও, বালুচিস্তানের ভাগ্যে জোটেনি কিছুই। বরং মিলেছে শুধু অবহেলা-অত্যাচার।</p>\r\n\r\n<p style=\"text-align:justify\">বালোচ, পিওকে-র বিক্ষোভকারীদের মধ্যে যে যোগাযোগ রয়েছে, তার ইঙ্গিত মিলেছে বালুচ স্বাধীনতাকামী নেতা তথা মানবাধিকার কর্মী মির ইয়ার বালুচের বক্তব্যেও। বলেছেন, ‘১৯৪৭-এ মেকি স্বাধীনতার পরেই কাশ্মীরের দিকে নজর দিয়েছিল পাকিস্তান সরকার। সেখানে অশান্তি পাকিয়ে, অবৈধ ভাবে দখলদারি চালিয়ে অশান্তি তৈরি করে রেখেছে। কাশ্মীরের পরে ওরা হামলা চালায় বালুচিস্তানে। আবার পূর্ব বঙ্গে লক্ষ লক্ষ মানুষকে হত্যা করেছে এরা। গোটা পৃথিবী পাক-ভূমি থেকে উদ্ভুত সন্ত্রাসের শিকার।’ মিরের বক্তব্য, বালুচিস্তান হোক বা পাক অধিকৃত কাশ্মীর, এই সব এলাকার বাসিন্দাদের এ দেশের মূল জনগোষ্ঠী বলে মনে করা হয় না। একবার পাক কাশ্মীরের আইজি আফতাব ইকবাল মন্তব্য করেছিলেন, এক হাজার কাশ্মীরির মৃত্যু হলে আখেরে পাকিস্তানেরই উন্নতি হবে। ফলে বোঝাই যায়, পাক সেনার কাছে কাশ্মীরিদের মূল্য আর কতটা!</p>\r\n\r\n<p style=\"text-align:justify\">একই অবস্থা বালোচদেরও। উপমহাদেশ থেকে ব্রিটিশ-শাসন অবলুপ্ত হওয়ার পরে ১৯৪৭ সালের ১১ আগস্ট বালুচিস্তানের স্বাধীনতা ঘোষণা করা হয়েছিল। কিন্তু তথাকথিত ‘আজাদ কাশ্মীর’-এর মতো বালুচিস্তানেও সেনা পাঠিয়ে পাকিস্তান দখলদারি চালিয়েছে। পিঠে বন্দুকের নল ঠেকিয়ে দশকের পর দশক পাক অধিকৃত কাশ্মীরের মানুষের সঙ্গেও অন্যায় করা হয়েছে। উন্নয়নের সিকিভাগও তাঁদের কাছে পৌঁছয়নি। ‘সম্পদ লুটের বদলে আমরা সবাই শুধু অবহেলা-অনুন্নয়ন উপহার পেয়েছি। পাক সরকার নিজের কোষাগার খসিয়ে কেন পাক অধিকৃত কাশ্মীরের উন্নয়ন করতে যাবে!’ অভিযোগ মির ইয়ার বালোচের। একই সুর শোনা গিয়েছে রাওয়ালকোটের ইদগাহ ময়দানের বিশাল সমাবেশে। যেখানে জেএএসি-র নেতা সর্দার আমান খান বলেছেন, ‘পিওকে পাকিস্তানের অংশ নয়। আমরা এই দেশের কেউ নই। আমাদের কোনও প্রয়োজন নেই পাকিস্তানকে। বরং পাকিস্তানই মরিয়া হয়ে আমাদের রেখে দিতে চায়। শুধু কাগুজে স্বাধীনতা নয়। আমরা চাই নিরঙ্কুশ স্বাধীনতা। আমরাই আমাদের এলাকা নিয়ে শেষ কথা বলব।’ সুর মেলান উপস্থিত জনতা। স্লোগান ওঠে, ‘স্বাধীনতা চাই। দূর হটো শেহবাজ সরকার। দূর হটো মুনিরের সেনা।’</p>\r\n\r\n<p style=\"text-align:justify\">রাতের ঘুম উবে যাওয়ার উপক্রম পাক প্রধানমন্ত্রী শেহবাজ শরিফ এবং সেনা সর্বাধিনায়ক আসিম মুনিরের। পাক সেনার গুলিতে জমছে লাশের পাহাড়। ইসলামাবাদের সেন্টার ফর দ্য স্টাডি অব ইসলাম অ্যান্ড ডিকলোনাইজেশনের শীর্ষ কর্তা জুনাইদ এস আহমদ বলছেন, ‘যে রাষ্ট্র বালুচদের ভিন্নমতকে রাষ্ট্রদ্রোহ, পশতুদের ভিন্নমতকে সন্ত্রাসবাদ, নির্বাচনী ভিন্নমতকে দেশদ্রোহ এবং কাশ্মীরিদের ভিন্নমতকে ষড়যন্ত্র বলে আখ্যা দেয়, সেই রাষ্ট্র জাতিকে রক্ষা করছে না। আসলে নিজের সদর দপ্তরকে রক্ষা করছে। অচিরেই হয়তো আর কোনো ‘ভালো’ পাকিস্তানি অবশিষ্ট থাকবে না। থাকবে শুধু সন্দেহভাজন মানুষ, যারা শ্রেণিবিন্যাস, শাস্তি এবং নীরবতার দেশপ্রেমী শিষ্টাচার শেখার অপেক্ষায় থাকবে। এর অর্থ এই নয় যে ‘সিকিউরিটি স্টেট’-র শত্রুদের পরাজিত করা। বরং এর অর্থ, তারা গোটা দেশকেই নিজেদের শত্রুতে পরিণত করা।’</p>\r\n\r\n<p style=\"text-align:justify\">পিওকে-র বিশিষ্ট নেতা তথা ইউনাইটেড কাশ্মীর পিপলস ন্যাশনাল পার্টি প্রধান জামিল মাকসুদের সাম্প্রতিক বয়ান তারই ইঙ্গিত দিয়েছে। জেনেভায় সংবাদসংস্থা এএনআই-কে বলেছেন, পাকিস্তান একটি ‘দুর্বৃত্ত রাষ্ট্র’। ভারতের সঙ্গে একত্র হতে চায় পাক-অধিকৃত কাশ্মীর!</p>\r\n', 'uploads/news/news_1786362587_2138.jpg', 'Pakistan', 4, NULL, 'মৃণালকান্তি দাস', 'published', 0, '2026-08-10 10:35:47', '2026-08-12 12:32:57'),
(2, 'তারেকের প্রতিরক্ষা উপদেষ্টার সঙ্গে বৈঠক ‘র’ প্রধানের', 'তারেকের-প্রতিরক্ষা-উপদেষ্টার-সঙ্গে-বৈঠক-র-প্রধানের', '<p style=\"text-align:justify\">প্রাক্তন প্রধানমন্ত্রী শেখ হাসিনার প্রত্যর্পণের দাবিতে অনড় বাংলাদেশ। বিষয়টি নিয়ে নয়াদিল্লির সঙ্গে ফের কূটনৈতিক টানাপোড়েন শুরু হয়েছে ঢাকার। সম্প্রতি দিল্লিতে হাসিনার সাংবাদিক সম্মেলন উত্তাপ আরও বৃদ্ধি করেছে। এরইমধ্যে বাংলাদেশ সফরে গেলেন ভারতের গোয়েন্দা সংস্থা &lsquo;র&rsquo;এর প্রধান পরাগ জৈন। সোমবার প্রধানমন্ত্রী তারেক রহমানের প্রতিরক্ষা বিষয়ক উপদেষ্টা ব্রিগেডিয়ার জেনারেল (অবসরপ্রাপ্ত) ডঃ এ কে এম শামসুল ইসলামের সঙ্গে বৈঠক করেন তিনি। একইদিনে তারেকের সঙ্গে বৈঠক করেন ভারতীয় হাই কমিশনার দীনেশ ত্রিবেদী। আলোচনার অন্যতম বিষয় ছিল হাসিনার প্রত্যর্পণ। আগামী মাসে ভারতে ব্রিকস সম্মেলন। এই সম্মেলনে তারেককে আমন্ত্রণ জানিয়েছে ভারত। এহেন পরিস্থিতিতে পরাগ-শামসুল বৈঠককে তাৎপর্যপূর্ণ বলে দেখছে ওয়াকিবহাল মহল। যদিও সংশ্লিষ্ট বৈঠক নিয়ে কোনো আনুষ্ঠানিক বিবৃতি দেয়নি ভারত সরকার। প্রসঙ্গত, রবিবার প্রতিনিধি দল নিয়ে ঢাকায় পৌঁছান পরাগ। বাংলাদেশের ডিরেক্টরেট জেনারেল অব ফোর্সেস ইন্টেলিজেন্সের আমন্ত্রণেই তাঁদের এই সফর। দিল্লি ফেরার আগে স্বরাষ্ট্রমন্ত্রী সালাউদ্দিন আহমেদ ও অন্যান্য এজেন্সির প্রধানদের সঙ্গেও বৈঠক করেন তাঁরা।</p>\r\n', 'uploads/news/news_1786537912_6223.webp', 'Bangladesh,Dhaka,Tarek', 4, NULL, 'অ্যাডমিন', 'published', 1, '2026-08-12 12:31:52', '2026-08-27 13:02:04'),
(3, 'পালিয়েও শেষরক্ষা হল না, আর জি কর কাণ্ডে ওড়িশা থেকে গ্রেপ্তার নির্মল ঘোষ', 'পালিয়েও-শেষরক্ষা-হল-না-আর-জি-কর-কাণ্ডে-ওড়িশা-থেকে-গ্রেপ্তার-নির্মল-ঘোষ', '<p style=\"text-align:justify\">আর জি কর কাণ্ডে পানিহাটির প্রাক্তন বিধায়ক নির্মল ঘোষকে গ্রেপ্তার করল পুলিশ। তড়িঘড়ি অভয়ার দেহ সৎকার করে প্রমাণ লোপাটের অভিযোগ ছিল তাঁর বিরুদ্ধে। এনিয়ে সোমবার খড়দহ থানায় লিখিত অভিযোগ করেন অভয়ার বাবা। দায়ের হয় এফআইআর। তার ভিত্তিতেই নির্মলকে গ্রেপ্তার করা হয়েছে বলে খবর।</p>\r\n\r\n<p style=\"text-align:justify\">আর জি কাণ্ডে শুরু থেকেই বিতর্কে নির্মল ঘোষের ভূমিকা। ময়নাতদন্তের পরে দ্রুততার সঙ্গে অভয়ার দেহ সৎকারে তিনি বিশেষভাবে তৎপর ছিলেন বলে অভিযোগ। এমনকি সে সময় তোয়াক্কা করা হয়নি পরিবারের মতামত। যে কারণে তাঁকে একাধিকবার জেরাও করেছে মামলার কেন্দ্রীয় তদন্তকারী সংস্থা সিবিআই।<br />\r\nগত শনিবার আর জি কর কাণ্ডের বর্ষপূর্তি উপলক্ষ্যে এক অনুষ্ঠানে এনিয়ে ফের সরব হন মুখ্যমন্ত্রী শুভেন্দু অধিকারী। দেহ সৎকারের ঘটনার নতুন করে তদন্ত প্রয়োজন বলে মন্তব্য করেন তিনি। বিষয়টি গুরুত্ব দিয়ে খতিয়ে দেখতে নির্দেশ দেন পুলিশকে। এর পরে সোমবার পুলিশে অভিযোগ দায়ের করেন অভয়ার বাবা। তাতে নির্মল সহ তিনজনের নাম ছিল। তার পর থেকে ফেরার ছিলেন অভিযুক্ত পানিহাটির প্রাক্তন তৃণমূল বিধায়ক। ফোনও বন্ধ ছিল তাঁর। কিন্তু শেষরক্ষা হল না। আজ ওড়িশা থেকে নির্মলকে গ্রেপ্তার করা হয়েছে বলে সূত্রের খবর। তাঁকে সড়ক পথে কলকাতায় আনা হচ্ছে বলে জানা গিয়েছে।</p>\r\n', 'uploads/news/news_1786615487_8865.webp', '', 2, 2, 'অ্যাডমিন', 'published', 1, '2026-08-13 10:04:47', '2026-08-27 12:28:42'),
(4, 'ভারতের বিরুদ্ধে টেস্ট সিরিজ় শুরুর আগে শ্রীলঙ্কাকেই এগিয়ে রাখছেন ধনঞ্জয়', 'ভারতের-বিরুদ্ধে-টেস্ট-সিরিজ়-শুরুর-আগে-শ্রীলঙ্কাকেই-এগিয়ে-রাখছেন-ধনঞ্জয়', '<p style=\"text-align:justify\">আত্মবিশ্বাসী তো বটেই, একই সঙ্গে প্রতিজ্ঞাবদ্ধ। ভারতের বিরুদ্ধে আসন্ন দুই টেস্টের সিরিজ় শুরুর আগে শ্রীলঙ্কা অধিনায়ক ধনঞ্জয় ডি সিলভা সাফ বলছেন, &lsquo;আমাদের টিম যথেষ্ট ব্যালান্সড। স্পিনাররা অবশ্যই বড় ভূমিকা নেবে। আমরা জানি, গলের উইকেট ঠিক কীরকম হয়। প্রথম দিকে উইকেট ভালো থাকে, কিন্তু তৃতীয় দিন থেকেই স্পিনাররা সাহায্য পায়। আমরা এখানকার পরিস্থিতি জানি, সে জন্যই আমরা সামান্য হলেও ভারতের থেকে এগিয়ে শুরু করব।&rsquo; প্রথম টেস্ট শুরু হচ্ছে গলে, আগামিকাল ১৫ অগস্ট।</p>\r\n\r\n<p style=\"text-align:justify\">টিম ইন্ডিয়ার টেস্ট টিমে এ বার নেই তিন নিয়মিত প্লেয়ার। জশপ্রীত বুমরা চোটের জন্য নেই, ঠিক তেমনই নেই সাই সুদর্শন ও ওয়াশিংটন সুন্দর। ধনঞ্জয়ের কথায়, &lsquo;বুমরার না থাকা অবশ্যই ভারতের পক্ষে বড় ধাক্কা। যার সুবিধে পাব আমরা।&rsquo; ভারত গত দু&rsquo;বছরে দেশের মাঠে পরপর দুটো সিরিজ় হেরেছে নিউ জি়ল্যান্ড ও দক্ষিণ আফ্রিকার বিরুদ্ধে। তা নিয়ে ধনঞ্জয় বলছেন, &lsquo;ভারত দেশের মাঠে দুটো সিরিজ় স্পিন ভালো খেলতে পারেনি ঠিকই, কিন্তু তার মানে এই নয় যে ভারতীয় ব্যাটাররা স্পিন খেলতে পারে না। আমি নিশ্চিত, ওরা এই সিরিজ়ে ঘুরে দাঁড়াতে চাইবে।&rsquo; ধনঞ্জয়ের মতে, এই সিরিজ়ে ভারতীয় ব্যাটারদের মধ্যে সবচেয়ে বিপজ্জনক হতে পারেন কেএল রাহুল। তাঁর কথায়, &lsquo;রাহুল এখানে ২০১৭ সালের সিরিজ়ে খেলেছিল। এখানকার উইকেট সম্পর্কে ওর ভালো অভিজ্ঞতা আছে। ওর অভিজ্ঞতা গুরুত্বপূর্ণ হবে।&rsquo;</p>\r\n\r\n<p style=\"text-align:justify\">চোটের জন্য শ্রীলঙ্কা টিমে নেই পাথুম নিশাঙ্কা ও কুশল মেন্ডিস। তিন বছর পরে টেস্ট টিমে ফেরানো হয়েছে উইকেটকিপার ব্যাটার নিরোশান ডিকওয়েলাকে। তবে শ্রীলঙ্কার প্রধান ভরসা বাঁ হাতি স্পিনার প্রভাত জয়সূর্য। তিনি ১১ টেস্টে গলের মাঠে ৮১ উইকেট নিয়েছেন।</p>\r\n', 'uploads/news/news_1787745041_2357.jpg', 'India, Cricket, Cricket News', 6, NULL, 'সব্যসাচী সরকার', 'published', 1, '2026-08-26 11:50:41', '2026-08-31 11:47:45'),
(5, 'ক্যামাক স্ট্রিটে অভিষেকের অফিসের সাইনবোর্ড খোলা নিয়ে ধুন্ধুমারের পর হাইকোর্টে তৃণমূল', 'ক্যামাক-স্ট্রিটে-অভিষেকের-অফিসের-সাইনবোর্ড-খোলা-নিয়ে-ধুন্ধুমারের-পর-হাইকোর্টে-তৃণমূল', '<p>কলকাতার ক্যামাক স্ট্রিটে অভিষেক বন্দ্যোপাধ্যায়ের কার্যালয় থেকে সাইনবোর্ড খুলে নেওয়ার ঘটনায় কলকাতা হাই কোর্টের দ্বারস্থ হল তৃণমূল কংগ্রেস। শুক্রবার সকালে দলের আইনজীবী কিশোর দত্ত বিচারপতি রাজা বসুচৌধুরীর এজলাসে বিষয়টি উত্থাপন করে দ্রুত শুনানির আর্জি জানান। বিচারপতি মামলা দায়ের করার অনুমতি দিয়ে জানান, উপযুক্ত প্রক্রিয়ার মাধ্যমে মামলার নম্বর নিয়ে এলে এবং বিপক্ষকে জানালে শুক্রবারই এই মামলার শুনানি হবে।<br />\r\nজানা গিয়েছে, ক্যামাক স্ট্রিটে তিন হাজার স্কোয়ার ফুটের বেশি জায়গা জুড়ে থাকা অভিষেকের ওই কার্যালয়ের মাথায় &lsquo;অল ইন্ডিয়া তৃণমূল কংগ্রেস&rsquo; লেখা একটি বড় বিলবোর্ড ছিল। বৃহস্পতিবার বিকেল পৌনে ৫টা নাগাদ কলকাতা পুরসভার কর্মীরা পুলিশকে সঙ্গে নিয়ে ওই সাইনবোর্ডটি খুলতে গেলে ধুন্ধুমার পরিস্থিতির সৃষ্টি হয়।<br />\r\n<br />\r\nসাইনবোর্ড খোলা আটকাতে পুরসভা ও পুলিশের কর্মীদের প্রবল বাধা দেন উপস্থিত তৃণমূল নেতা-কর্মীরা।&nbsp;<br />\r\n<br />\r\nঅভিষেক বন্দ্যোপাধ্যায় এবং দলের রাজ্যসভার সাংসদ ডেরেক ও&rsquo;ব্রায়েন-সহ অন্যান্যরা পুলিশের সঙ্গে দফায় দফায় বচসা ও ধস্তাধস্তিতে জড়িয়ে পড়েন। ডেরেক ও&rsquo;ব্রায়েন সিঁড়িতে শুয়ে পড়েও বাধা দেওয়ার চেষ্টা করেন বলে অভিযোগ। তবে শেষ পর্যন্ত পুরসভার কর্মীরা বিলবোর্ডটি সরিয়ে দেন। যদিও সামান্য সময়ের ব্যবধানে তৃণমূল ফের সেখানে নতুন বিলবোর্ড লাগিয়ে দেয়। সরকারি কাজে বাধার অভিযোগে পুলিশ ইতিমধ্যেই ১৩ জনকে গ্রেপ্তার করেছে।</p>\r\n', 'uploads/news/news_1787990663_1348.webp', '', 2, NULL, 'আসলাম হোসেন', 'published', 1, '2026-08-28 09:32:27', '2026-08-29 08:04:23'),
(6, 'ক্রিকেট দেখে শেখা উচিত? ব্রাজ়িল-উরুগুয়ে ম্যাচ নিয়ে AIFF-কে টিপস সৌরভের', 'ক্রিকেট-দেখে-শেখা-উচিত-ব্রাজ়িল-উরুগুয়ে-ম্যাচ-নিয়ে-aiff-কে-টিপস-সৌরভের', '<p style=\"text-align:justify\">পানামা, ব্রাজ়িল ও উরুগুয়ের বিরুদ্ধে খেলবে ভারতের সিনিয়র পুরুষ দল। ইতিমধ্যেই এই সিদ্ধান্ত নিয়ে ব্যাকফুটে AIFF। ভাইচুং ভুটিয়ার মতো একাধিক প্রাক্তন তারকা এই সিদ্ধান্তের নিন্দা করেছে। ভারতীয় ফুটবলের এই কঠিন সময়ে কেন এত খরচ করা হচ্ছে সেই প্রশ্ন তোলা হয়েছে। এই বিষয়ে এ বার মুখ খুললেন ভারতীয় ক্রিকেটের কিংবদন্তি সৌরভ গঙ্গোপাধ্যায়।</p>\r\n\r\n<p style=\"text-align:justify\">ভারতীয় ফুটবলের মানোন্নয়নের জন্য বিশ্বের শীর্ষ দলগুলির বিরুদ্ধে নিয়মিত খেলা প্রয়োজন বলে বার্তা দিলেন সৌরভ। পানামা, ব্রাজ়িল ও উরুগুয়ের বিরুদ্ধে ম্যাচের এই সুযোগ যেন কেবল এককালীন কোনও ইভেন্টে সীমাবদ্ধ না থাকে, সে বিষয়েও ফেডারেশনকে সতর্ক করেছেন সৌরভ।</p>\r\n\r\n<p style=\"text-align:justify\">বিশ্বকাপ খেলা তিনটে দলের বিরুদ্ধে ভারতের ম্যাচ নিয়ে নিজের প্রতিক্রিয়া জানাতে গিয়ে সৌরভ বলেন, &lsquo;বড় দলের বিরুদ্ধে খেলাটা অবশ্যই দারুণ ব্যাপার। বড় প্রতিপক্ষের বিরুদ্ধে না খেলার কোনও কারণই নেই। এতে আমাদের ফুটবলারদের অভিজ্ঞতা বাড়বে এবং সর্বোচ্চ পর্যায়ের ফুটবলে নিজেদের মান যাচাই করার সুবর্ণ সুযোগ মিলবে।&rsquo;</p>\r\n\r\n<p style=\"text-align:justify\">তবে এই ধরনের মেগা ম্যাচের প্রভাব তখনই দীর্ঘস্থায়ী হবে, যখন তা রুটিনে পরিণত হবে। প্রাক্তন বিসিসিআই সভাপতির মতে, বছরে মাত্র এক-দু&rsquo;টি প্রীতি ম্যাচ খেলে ভারতীয় ফুটবলের ছবি আমূল বদলানো অসম্ভব। ভারতীয় ফুটবলারদের উন্নতি করতে হলে সারা বছর ধরেই এমন শক্তিশালী দলগুলির মোকাবিলার সুযোগ তৈরি করে দিতে হবে। সৌরভের কথায়, &lsquo;প্লেয়ারদের তৈরি করার জন্য এই ধরনের ম্যাচ সারা বছর ধরেই হওয়া দরকার। আমি সবসময় বিশ্বাস করি, নিজের চেয়ে শক্তিশালী প্রতিপক্ষের বিরুদ্ধে মাঠে নামলেই নিজের খেলার আসল উন্নতি ঘটে।&rsquo;</p>\r\n\r\n<p style=\"text-align:justify\">এই প্রসঙ্গের ব্যাখ্যা দিতে গিয়ে ভারতীয় ক্রিকেটের সাফল্যের দৃষ্টান্ত তুলে ধরেন মহারাজ। তিনি মনে করেন, বিভিন্ন কন্ডিশন ও ফরম্যাটে বিশ্বসেরা দলগুলির বিরুদ্ধে প্রতিনিয়ত লড়াই করেই ভারতীয় ক্রিকেট আজকের এই শক্তিশালী জায়গায় পৌঁছেছে। সৌরভের পরামর্শ, &lsquo;ক্রিকেটের দিকে তাকালে দেখা যাবে, ওরা সারা বছরই বিশ্বমানের দলগুলির বিরুদ্ধে নিয়মিত খেলে। আর সে কারণেই ক্রিকেটাররা নিজেদের মান আরও উন্নত করতে পেরেছে। ফুটবলেও অবিকল এই নীতিই অনুসরণ করতে হবে।&rsquo;</p>\r\n\r\n<p style=\"text-align:justify\">AIFF-এর কাছে সৌরভ আশা প্রকাশ করেছেন, তারা কেবল এই উইন্ডোতেই থেমে না থেকে ভবিষ্যতে ভারতীয় ফুটবলের জন্য আরও ধারাবাহিক ও শক্তিশালী আন্তর্জাতিক ক্যালেন্ডার তৈরি করবে। ব্রাজ়িল ও উরুগুয়ের বিরুদ্ধে খেলাকে তিনি দীর্ঘমেয়াদি পথচলার ইতিবাচক সূচনা হিসেবেই দেখছেন।</p>\r\n', 'uploads/news/news_1788176691_8631.jpg', 'সৌরভ গঙ্গোপাধ্যায়, ভারতীয় ফুটবল দল, ফুটবল সংবাদ, এআইএফএফ', 6, NULL, 'অ্যাডমিন', 'published', 1, '2026-08-31 11:41:53', '2026-08-31 11:46:55'),
(7, 'হরমুজ প্রণালীতে অত্যাধুনিক মার্কিন সাবমেরিন আটকের দাবি ইরানের, চরমে সংঘাত', 'হরমুজ-প্রণালীতে-অত্যাধুনিক-মার্কিন-সাবমেরিন-আটকের-দাবি-ইরানের-চরমে-সংঘাত', '<p style=\"text-align: justify;\">ইরানের পাঁচটি তেলের ট্যাঙ্কারে আমেরিকার হামলার পর এবার বড়সড় পাল্টা পদক্ষেপ করল তেহরান। হরমুজ প্রণালীতে একটি অত্যাধুনিক মার্কিন সাবমেরিন বাজেয়াপ্ত করার দাবি করেছে ইসলামিক রেভলিউশনারি গার্ড কর্পস (আইআরজিসি)। ইতিমধ্যেই আইআরজিসি-র মুখপত্র &#39;সেফা নিউজ&#39;-এর পক্ষ থেকে &#39;ডাইভ-এলডি&#39; নামের ওই মার্কিন জলযানটির ছবি ও ভিডিও প্রকাশ্যে আনা হয়েছে। এই ঘটনার জেরে ছ&rsquo;মাস ধরে চলা আমেরিকা-ইরান যুদ্ধের সমীকরণ নতুন দিকে ঘুরতে পারে বলে মনে করছে ওয়াকিবহাল মহল।</p>\r\n\r\n<p style=\"text-align: justify;\">আইআরজিসি-র দাবি, আটক করা জলযানটি আমেরিকার একটি অত্যন্ত আধুনিক ও &lsquo;স্মার্ট&rsquo; সাবমেরিন, যা মূলত বড় জাহাজের সহায়ক সাবমার্সিবল হিসেবে কাজ করে। শুধু জলভাগেই নয়, আকাশপথেও কড়া প্রতিরোধের দাবি করেছে খামেনেইয়ের দেশ। তাদের আকাশ প্রতিরক্ষা ব্যবস্থা হরমুজ প্রণালীর কাছে আমেরিকার একটি এমকিউ-৯ রিপার ড্রোনকেও গুলি করে নামিয়েছে বলে আইআরজিসি-র বিবৃতিতে জানানো হয়েছে।<br />\r\nইরানের এই দাবির প্রেক্ষিতে পাল্টা বিবৃতি প্রকাশ করেছে মার্কিন সেনাও।</p>\r\n\r\n<p style=\"text-align: justify;\">আমেরিকার তরফে জানানো হয়েছে, জলসীমায় নজরদারি চালানোর সময় তাদের একটি ডুবো ড্রোন যান্ত্রিক গোলযোগের কবলে পড়েছিল। তবে ইরান যে ড্রোনটি বাজেয়াপ্ত করার কথা বলছে, সেটি একই ড্রোন কি না, তা বিবৃতিতে স্পষ্ট করেনি আমেরিকা। পাশাপাশি মার্কিন সেনার দাবি, ওই সাবমার্সিবলটিতে কোনও ধরনের স্পর্শকাতর তথ্য বা রেডার সরঞ্জাম মজুত ছিল না।</p>\r\n\r\n<p style=\"text-align: justify;\">উল্লেখ্য, গত ২৮ ফেব্রুয়ারি থেকে শুরু হওয়া এই যুদ্ধে লাগাতার আক্রমণ ও একাধিক নিষেধাজ্ঞা চাপানোর পরেও ইরানকে সম্পূর্ণ কোণঠাসা করতে পারেনি ওয়াশিংটন। ব্যর্থ হয়েছে আমেরিকার শর্তে হওয়া শান্তি আলোচনাও। হরমুজ প্রণালীতে প্রাণহানি এড়াতে আমেরিকা যে স্বয়ংক্রিয় ডুবো ড্রোন ব্যবহার করছে, সাম্প্রতিক এই ঘটনা সেই জল্পনাকেই প্রমাণ করল বলে মনে করছেন বিশেষজ্ঞরা।</p>\r\n', 'uploads/news/news_1788954118_3073.webp', 'ইরান', 4, NULL, 'অ্যাডমিন', 'published', 1, '2026-09-09 11:41:23', '2026-09-09 11:48:34'),
(8, 'কেরলে হড়পা সঙ্গে ভূমিধস, মৃত ৫, নিখোঁজ একাধিক, পরিস্থিতি মোকাবিলায় কড়া নির্দেশ প্রশাসনের', 'কেরলে-হড়পা-সঙ্গে-ভূমিধস-মৃত-৫-নিখোঁজ-একাধিক-পরিস্থিতি-মোকাবিলায়-কড়া-নির্দেশ-প্রশাসনের', '<p>হড়পা ও ভূমিধসে (<strong>Landslide</strong>) বিপর্যস্ত হয়ে পড়েছে কেরল (<strong>Kerala flash flood</strong>)। এই প্রাকৃতিক দুর্যোগে এখনও পর্যন্ত কমপক্ষে পাঁচজনের মৃত্যুর খবর পাওয়া গিয়েছে। পাশাপাশি নিখোঁজ রয়েছেন আরও দু&rsquo;জন। পরিস্থিতির অবনতি হওয়ায় প্রশাসনের পক্ষ থেকে প্রতি ঘণ্টায় অবস্থা পর্যালোচনা করার কড়া নির্দেশ জারি করা হয়েছে।</p>\r\n\r\n<p>গত রবিবার মুখ্যমন্ত্রীর কার্যালয় থেকে প্রকাশিত এক বিবৃতিতে জানানো হয় যে, মুখ্যমন্ত্রী ভি ডি সতীশনের সুনির্দিষ্ট নির্দেশ পাওয়ার পর পরই দুর্যোগ ব্যবস্থাপনা কর্তৃপক্ষের কমিশনার বিঘ্নেশ্বরী আইএএস ইমুক্কি ও কোট্টায়ামের জেলা শাসকদের সঙ্গে উচ্চপর্যায়ের বৈঠক করেছেন। ওই দুই জেলায় আবহাওয়ার বিপজ্জনক অবস্থার কথা জানিয়ে আগাম সতর্কতাও পাঠানো হয়েছে। এছাড়া ঝুঁকিপূর্ণ অঞ্চলে বসবাসকারী সাধারণ মানুষকে দ্রুত নিরাপদ আশ্রয়ে সরিয়ে নেওয়ার জন্য জেলা প্রশাসনকে নির্দেশ দেওয়া হয়েছে।</p>\r\n\r\n<p>মালপ্পুরম জেলার নীলাম্বর-আমারমবলম এলাকায় কোট্টাপুঝা নদীর জলের তোড়ে ভেসে গিয়ে পাঁচজনের একটি দলের মর্মান্তিক পরিণতি ঘটে। ওই দলের মধ্য থেকে দুজনের মৃত্যু নিশ্চিত করা হয়েছে এবং এখনও দুজন নিখোঁজ রয়েছেন। পুলিশ সূত্রে জানা যায়, ভান্দুর থেকে আসা ওই পাঁচজনের দলটি গত রবিবার সন্ধ্যায় নদীতে নেমেছিল। হঠাৎ করেই হড়পা আসায় জলের স্তর অস্বাভাবিকভাবে বেড়ে যায় এবং মুহূর্তের মধ্যে তারা স্রোতে ভেসে যান। স্থানীয় এক বাসিন্দা সাহসিকতা দেখিয়ে একজনকে জীবিত উদ্ধার করেন এবং ফায়ার সার্ভিস দল দুজনের মরদেহ উদ্ধার করতে সক্ষম হলেও বাকি দুজনের খোঁজ এখনও মেলেনি। এই ঘটনার পরই মুখ্যমন্ত্রী ঘটনাস্থলে অবিলম্বে বিশেষ দুর্যোগ ব্যবস্থাপনা বাহিনী পাঠানোর নির্দেশ দেন।</p>\r\n\r\n<p>অন্যদিকে, কোট্টায়াম জেলার থীকয়ের কাছে ভেলাথাঞ্জেরিতে রবিবার সন্ধ্যায় ঘটা ভূমিধসে তামিলনাড়ুর এক মহিলার মৃত্যু হয়েছে এবং তার সঙ্গী আহত হয়েছেন। চেন্নাইয়ের জওহর নগরের বাসিন্দা পঁয়ত্রিশ বছর বয়সী সংগীতা অরুল লাল বাগমন থেকে স্কুটারে চড়ে ফেরার সময় হঠাৎ পাহাড়ের মাটি ধসে তাঁর ওপর পড়ে। তার সঙ্গী আহত অবস্থায় প্রাণে বেঁচে গেলেও হাসপাতালে চিকিৎসাধীন রয়েছেন। এছাড়া ইদুক্কি জেলার কোত্তাকাম্বুরে বৃষ্টির হাত থেকে বাঁচতে একটি টিনের ছাউনিতে আশ্রয় নেওয়া তিনজন ব্যক্তি ভূমিধসের কবলে পড়েন। গতকাল পাহাড়ের ঢাল ভেঙে বিশাল পরিমাণ মাটি ওই ছাউনির ওপর আছড়ে পড়ে। এর ফলে ঘটনাস্থলেই দুজন নিহত হন এবং আহত এক মহিলাকে দ্রুত চিকিৎসার জন্য হাসপাতালে নিয়ে যাওয়া হয়।</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>আইএমডি জানিয়েছে, আগামী চারদিন কেরলের বিভিন্ন অঞ্চলে ভারী থেকে অতি ভারী বৃষ্টি অব্যাহত থাকতে পারে। পাশাপাশি কয়েকটি এলাকায় বজ্রবিদ্যুৎ সহ ঝড়ের পূর্বাভাসও দেওয়া হয়েছে। পরিস্থিতি বিবেচনা করে কোট্টায়াম ও ইদুক্কি জেলায় বৃষ্টির সতর্কতা বাড়িয়ে &lsquo;কমলা&rsquo; বা &lsquo;অরেঞ্জ&rsquo; অ্যালার্ট (<strong>Orange Alert</strong>) জারি করা হয়েছে। উল্লেখ্য, চলতি মরশুমে কেরলে মৌসুমী বায়ুর প্রভাব তুলনামূলকভাবে দুর্বল ছিল। গত ১ জুন থেকে ১৭ সেপ্টেম্বর পর্যন্ত রাজ্যটিতে স্বাভাবিকের চেয়ে ২৮ শতাংশ কম বৃষ্টিপাত রেকর্ড করা হয়েছিল।</p>\r\n', 'uploads/news/news_1789971445_1811.jpg', '', 2, NULL, 'উত্তরবঙ্গ সংবাদ', 'published', 1, '2026-09-21 02:47:25', '2026-09-21 06:17:25');

